mapper.update:
update inv_purchase_return_detail
set returned_quantity = #{returnedQuantity}
where detail_id = #{detailId}

mapper.select:
select d.detail_id, d.return_id, d.purchase_detail_id, d.product_id, d.quantity
from inv_purchase_return r force index (idx_ipr_purchase)
straight_join inv_purchase_return_detail d force index (idx_iprd_return) on d.return_id = r.return_id
where r.purchase_order_id = #{purchaseOrderId}
  and r.status in ('submitted', 'returned')

  and r.return_id != #{excludeReturnId}

order by r.return_id, d.detail_id
for update

select coalesce(sum(d.quantity), 0)
from inv_purchase_return_detail d
inner join inv_purchase_return r on r.return_id = d.return_id
where r.purchase_order_id = #{purchaseOrderId}
  and d.product_id = #{productId}
  and r.status in ('submitted', 'returned')

  and r.return_id != #{excludeReturnId}

select coalesce(sum(d.quantity), 0)
from inv_purchase_return_detail d
inner join inv_purchase_return r on r.return_id = d.return_id
where r.purchase_order_id = #{purchaseOrderId}
  and d.purchase_detail_id = #{purchaseDetailId}
  and r.status in ('submitted', 'returned')

  and r.return_id != #{excludeReturnId}
